// Баг #8d9eb38f (8d9eb38fafaf51be081b862d) — найден 14.10.2026, исправлен и принят 18.10.2026
//   (עבר QA, TestFlight 1.0.0 (20) + OTA, commit 6be8635). @known-bug снят 18.10.
// Сценарий: номер A не завершил регистрацию → «יצירת חשבון» → «חזרה» → вход номером B → «יצירת חשבון»:
//   поле 'מספר טלפון *' = B → 3 холодных перезапуска → поле каждый раз = B (не A и не мокап-номер 0501112233).
// Факт 18.10: A=0501112044, B=0501112055 — поле = подтверждённый номер, 3/3 перезапуска; «חזרה» на месте.
//   Номера A и B должны оба отличаться от мокап-номера 0501112233 (иначе тест не различит фикс и заглушку).
// Кейс: .qa/tests/registration/RG-08-create-account-phone-after-restart.md. Соседний принятый #bad2d0dd — RG-06.
// ВХОД И КОДЫ ДЕЛАЕТ ЧЕЛОВЕК (@manual-check). Запуск: QA_REG_MANUAL=1, иначе skip.
// РУЧНЫЕ ШАГИ (тест ждёт до 15 минут на каждом):
//  1) «בואו נתחיל» → НОВЫЙ номер A (без аккаунта, ≠ 0501112233) → «שילחו קוד אימות» → код. На «יצירת חשבון» ничего не заполнять.
//  2) После того как тест нажмёт «חזרה»: ДРУГОЙ новый номер B (без аккаунта, ≠ 0501112233) → код. На «יצירת חשבון» ничего не заполнять.
// Тест сам: «חזרה» (по accessibility name), холодный перезапуск (terminateApp/activateApp), чтение поля. Без тапов по координатам.
// Аккаунты не создаются (форма не отправляется). В конце — «חזרה» и вход USER1.
import { $, driver, expect } from '@wdio/globals';
import { byText, byLabel } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout, login } from '../../helpers/app.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { appId } from '../_lib/app-1310b.ts';
import { fieldValue } from '../_lib/app-1410.ts';

const CREATE = 'יצירת חשבון';
const LOGIN_TITLE = 'כניסה דרך מספר נייד';
const PHONE_LABEL = 'מספר טלפון *';
const MANUAL_WAIT = 900000;
const MOCK_PHONE = '0501112233';   // мокап-номер формы — в поле его быть не должно
const RESTARTS = 3;               // факт 18.10: 3/3 холодных перезапуска

async function coldRestart() {
  const id = appId();
  if (!id) throw new Error('нет APP_IOS_BUNDLE / APP_ANDROID_PACKAGE — холодный перезапуск невозможен');
  await driver.terminateApp(id);
  await driver.activateApp(id);
}

/** Поле 'מספר טלפון *' на «יצירת חשבון»: по accessibility name, запасной путь — TextField с label/placeholder «מספר טלפון». */
async function phoneField(): Promise<WebdriverIO.Element> {
  const lbl = (await byLabel(PHONE_LABEL)) as unknown as WebdriverIO.Element;
  if (await lbl.isExisting().catch(() => false)) return lbl;
  return (await (driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText").descriptionStartsWith("מספר טלפון")')
    : $('-ios predicate string:type == "XCUIElementTypeTextField" AND (label BEGINSWITH "מספר טלפון" OR placeholderValue BEGINSWITH "מספר טלפון")'))) as unknown as WebdriverIO.Element;
}

/** Последние 9 цифр номера (05X… и +972… сравниваются одинаково). */
const digits = (v: string) => v.replace(/\D/g, '').slice(-9);

async function phoneOnCreate(): Promise<string> {
  await expect(byText(CREATE)).toBeDisplayed({ wait: 30000 });
  const f = await phoneField();
  await f.waitForExist({ timeout: 15000 });
  return digits(await fieldValue(f));
}

async function leaveToLogin() {
  const back = await byLabel('חזרה');
  await expect(back).toBeDisplayed({ wait: 10000 });
  await back.click();
  await expect(byText(LOGIN_TITLE)).toBeDisplayed({ wait: 20000 });
}

/** Выйти, если вошли; если открыт экран незавершённой регистрации — выйти через «חזרה». */
async function ensureLoggedOutSafe() {
  if (await shown(byText(CREATE))) {
    const back = await byLabel('חזרה');
    if (await back.isDisplayed().catch(() => false)) await back.click();
    return;
  }
  if (await isLoggedIn()) await logout();
}

describe('Регистрация: номер на «יצירת חשבון» после смены номера и перезапуска', () => {
  beforeEach(function () {
    if (process.env.QA_REG_MANUAL !== '1') skipWith(this, 'вход двумя новыми номерами с OTP — вручную; запуск с QA_REG_MANUAL=1 и человеком у телефона');
  });

  it('RG-08 Номер A → «חזרה» → номер B → «יצירת חשבון» «מספר טלפון *» = B; после 3 холодных перезапусков поле остаётся B (не A, не мокап 0501112233) #8d9eb38f @manual-check', async function () {
    this.timeout(2400000);
    try {
      await ensureLoggedOutSafe();

      // 1. Номер A (человек) → «יצירת חשבון».
      console.log(`[RG-08] @manual-check: войдите НОВЫМ номером A и введите код; на «${CREATE}» ничего не заполнять. Тест ждёт до 15 минут…`);
      await (await byText(CREATE)).waitForDisplayed({ timeout: MANUAL_WAIT, interval: 3000, timeoutMsg: `не дождались «${CREATE}» (номер A)` });
      const a = await phoneOnCreate();
      const mock = digits(MOCK_PHONE);
      console.log(`[RG-08] номер A в поле: …${a.slice(-4)}`);
      expect({ aFilled: a.length === 9, aIsMock: a === mock }).toEqual({ aFilled: true, aIsMock: false });

      // 2. «חזרה» → экран входа.
      await leaveToLogin();

      // 3. Номер B (человек) → «יצירת חשבון»; поле = B (≠ A).
      console.log(`[RG-08] @manual-check: войдите ДРУГИМ новым номером B и введите код; на «${CREATE}» ничего не заполнять. Тест ждёт до 15 минут…`);
      let b = '';
      await driver.waitUntil(async () => {
        if (!(await shown(byText(CREATE)))) return false;
        const f = await phoneField();
        if (!(await f.isExisting().catch(() => false))) return false;
        b = digits(await fieldValue(f));
        return b.length > 0 && b !== a;
      }, { timeout: MANUAL_WAIT, interval: 3000, timeoutMsg: `не дождались «${CREATE}» с номером B (≠ A)` });
      console.log(`[RG-08] номер B в поле: …${b.slice(-4)}`);

      expect({ bIsMock: b === mock }).toEqual({ bIsMock: false });

      // 4. Холодный перезапуск ×3 → каждый раз «יצירת חשבון», в поле B (факт 14.10: A — баг; 18.10: B, 3/3).
      for (let i = 1; i <= RESTARTS; i++) {
        await coldRestart();
        const after = await phoneOnCreate();
        console.log(`[RG-08] перезапуск ${i}/${RESTARTS}: …${after.slice(-4)}`);
        expect({ restart: i, afterRestart: after.slice(-4), isB: after === b, isA: after === a, isMock: after === mock })
          .toEqual({ restart: i, afterRestart: b.slice(-4), isB: true, isA: false, isMock: false });
      }
    } finally {
      try {
        if (await shown(byText(CREATE))) await leaveToLogin();
        if (!(await isLoggedIn())) await login('USER1');
      } catch (e) {
        console.warn('[RG-08] вернуть вход USER1 вручную', e);
        await ensureAppReady().catch(() => {});
      }
    }
  });
});
